      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IEACAggregatorProxy} from "./interfaces/IEACAggregatorProxy.sol";

interface IUSDyOracleSource is IEACAggregatorProxy {
    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);

    function getRoundData(uint80 requestedRoundId)
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

contract USDyOracle is Ownable, IEACAggregatorProxy {
    error InvalidMultiplier(uint256 multiplierBps);
    error InvalidUsdcOracle(address oracle);
    error InvalidOracleDecimals(uint8 decimals);
    error NoAvailablePrice();

    event MultiplierUpdated(uint256 previousMultiplierBps, uint256 newMultiplierBps);
    event UsdcOracleUpdated(address previousUsdcOracle, address newUsdcOracle);

    uint256 public constant BPS_DENOMINATOR = 10_000;
    uint256 public constant MIN_MULTIPLIER_BPS = 10_000;
    uint256 public constant DEFAULT_MULTIPLIER_BPS = 11_400;
    uint256 public constant MAX_MULTIPLIER_BPS = 12_000;

    uint256 private constant SCALAR_RETURN_DATA_LENGTH = 32;
    uint256 private constant ROUND_DATA_RETURN_DATA_LENGTH = 160;
    uint8 private constant ORACLE_DECIMALS = 8;

    IUSDyOracleSource public usdcOracle;
    uint256 public multiplierBps;

    constructor(address _usdcOracle, address _safe) Ownable(_safe) {
        _setUsdcOracle(_usdcOracle);
        multiplierBps = DEFAULT_MULTIPLIER_BPS;
    }

    function setMultiplierBps(uint256 newMultiplierBps) external onlyOwner {
        if (newMultiplierBps < MIN_MULTIPLIER_BPS || newMultiplierBps > MAX_MULTIPLIER_BPS) {
            revert InvalidMultiplier(newMultiplierBps);
        }

        uint256 previousMultiplierBps = multiplierBps;
        multiplierBps = newMultiplierBps;

        emit MultiplierUpdated(previousMultiplierBps, newMultiplierBps);
    }

    function setUsdcOracle(address newUsdcOracle) external onlyOwner {
        _setUsdcOracle(newUsdcOracle);
    }

    function decimals() external pure override returns (uint8) {
        return ORACLE_DECIMALS;
    }

    function latestAnswer() external view override returns (int256) {
        return _scaleAnswer(usdcOracle.latestAnswer());
    }

    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)
    {
        (roundId, answer, startedAt, updatedAt, answeredInRound) = usdcOracle.latestRoundData();
        answer = _scaleAnswer(answer);
    }

    function latestTimestamp() external view override returns (uint256) {
        return usdcOracle.latestTimestamp();
    }

    function latestRound() external view override returns (uint256) {
        return usdcOracle.latestRound();
    }

    function getAnswer(uint256 roundId) external view override returns (int256) {
        return _scaleAnswer(usdcOracle.getAnswer(roundId));
    }

    function getRoundData(uint80 requestedRoundId)
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)
    {
        (roundId, answer, startedAt, updatedAt, answeredInRound) = usdcOracle.getRoundData(requestedRoundId);
        answer = _scaleAnswer(answer);
    }

    function getTimestamp(uint256 roundId) external view override returns (uint256) {
        return usdcOracle.getTimestamp(roundId);
    }

    function _setUsdcOracle(address newUsdcOracle) internal {
        if (newUsdcOracle == address(0) || newUsdcOracle.code.length == 0) {
            revert InvalidUsdcOracle(newUsdcOracle);
        }

        bytes memory returnData = _validatedStaticCall(
            newUsdcOracle, abi.encodeWithSelector(IEACAggregatorProxy.decimals.selector), SCALAR_RETURN_DATA_LENGTH
        );
        uint256 rawDecimals = abi.decode(returnData, (uint256));
        if (rawDecimals > type(uint8).max) {
            revert InvalidUsdcOracle(newUsdcOracle);
        }

        uint8 candidateDecimals = uint8(rawDecimals);
        if (candidateDecimals != ORACLE_DECIMALS) {
            revert InvalidOracleDecimals(candidateDecimals);
        }

        returnData = _validatedStaticCall(
            newUsdcOracle, abi.encodeWithSelector(IEACAggregatorProxy.latestAnswer.selector), SCALAR_RETURN_DATA_LENGTH
        );
        _requirePositiveAnswer(abi.decode(returnData, (int256)));

        _validatedStaticCall(
            newUsdcOracle,
            abi.encodeWithSelector(IEACAggregatorProxy.latestTimestamp.selector),
            SCALAR_RETURN_DATA_LENGTH
        );

        returnData = _validatedStaticCall(
            newUsdcOracle, abi.encodeWithSelector(IEACAggregatorProxy.latestRound.selector), SCALAR_RETURN_DATA_LENGTH
        );
        uint256 latestRoundId = abi.decode(returnData, (uint256));

        returnData = _validatedStaticCall(
            newUsdcOracle,
            abi.encodeWithSelector(IEACAggregatorProxy.getAnswer.selector, latestRoundId),
            SCALAR_RETURN_DATA_LENGTH
        );
        _requirePositiveAnswer(abi.decode(returnData, (int256)));

        _validatedStaticCall(
            newUsdcOracle,
            abi.encodeWithSelector(IEACAggregatorProxy.getTimestamp.selector, latestRoundId),
            SCALAR_RETURN_DATA_LENGTH
        );

        returnData = _validatedStaticCall(
            newUsdcOracle,
            abi.encodeWithSelector(IUSDyOracleSource.latestRoundData.selector),
            ROUND_DATA_RETURN_DATA_LENGTH
        );
        uint80 v3RoundId = _validateRoundData(newUsdcOracle, returnData);

        returnData = _validatedStaticCall(
            newUsdcOracle,
            abi.encodeWithSelector(IUSDyOracleSource.getRoundData.selector, v3RoundId),
            ROUND_DATA_RETURN_DATA_LENGTH
        );
        _validateRoundData(newUsdcOracle, returnData);

        address previousUsdcOracle = address(usdcOracle);
        usdcOracle = IUSDyOracleSource(newUsdcOracle);

        emit UsdcOracleUpdated(previousUsdcOracle, newUsdcOracle);
    }

    function _validatedStaticCall(address candidate, bytes memory callData, uint256 minimumReturnDataLength)
        internal
        view
        returns (bytes memory returnData)
    {
        bool success;
        (success, returnData) = candidate.staticcall(callData);
        if (!success || returnData.length < minimumReturnDataLength) {
            revert InvalidUsdcOracle(candidate);
        }
    }

    function _validateRoundData(address candidate, bytes memory returnData) internal pure returns (uint80 roundId) {
        uint256 rawRoundId;
        int256 answer;
        uint256 rawAnsweredInRound;
        (rawRoundId, answer,,, rawAnsweredInRound) =
            abi.decode(returnData, (uint256, int256, uint256, uint256, uint256));

        if (rawRoundId > type(uint80).max || rawAnsweredInRound > type(uint80).max) {
            revert InvalidUsdcOracle(candidate);
        }
        _requirePositiveAnswer(answer);

        roundId = uint80(rawRoundId);
    }

    function _requirePositiveAnswer(int256 answer) internal pure {
        if (answer <= 0) revert NoAvailablePrice();
    }

    function _scaleAnswer(int256 answer) internal view returns (int256) {
        _requirePositiveAnswer(answer);

        return answer * int256(multiplierBps) / int256(BPS_DENOMINATOR);
    }
}
"
